ALTER SESSION SET CURRENT_SCHEMA = LEHZ;

-- Carga de comunas con IDs reales de regiones 37 a 52.
-- Las 16 regiones YA EXISTEN: no se insertan nuevamente.
-- Es seguro volver a ejecutar este archivo: omite comunas ya registradas en su region.
-- Verifique antes que los IDs 37..52 correspondan a las regiones indicadas.

-- Comprobacion previa de regiones
SELECT ID_REGION, NOMBRE_REGION FROM LEHZ_REGION WHERE ID_REGION BETWEEN 37 AND 52 ORDER BY ID_REGION;

-- Insercion de 346 comunas (sin duplicar nombre dentro de la misma region)

COMMIT;

-- Verificacion
SELECT R.ID_REGION, R.NOMBRE_REGION, COUNT(C.ID_COMUNA) TOTAL_COMUNAS FROM LEHZ_REGION R LEFT JOIN LEHZ_COMUNA C ON C.ID_REGION = R.ID_REGION WHERE R.ID_REGION BETWEEN 37 AND 52 GROUP BY R.ID_REGION, R.NOMBRE_REGION ORDER BY R.ID_REGION;
